    const float* __restrict__ bias, OutPtrs outs, int B, int Bpad, int kbsW, int SW, int SE, int tmem_cols, int hint) {
  extern __shared__ uint8_t smem_raw[];
  __shared__ __align__(8) uint64_t fullW[kMaxSW], emptyW[kMaxSW], fullE[kMaxSE], emptyE[kMaxSE], accum;
  __shared__ uint32_t tmem_slot;
  const uint32_t wbase = (smem_u32(smem_raw) + 1023) & ~1023u;
  const uint32_t wStage = kbsW * kWBlk, eStage = Bpad * 128;
  const uint32_t ebase = wbase + SW * wStage;
  const int warp = threadIdx.x >> 5, lane = threadIdx.x & 31;
  const int m0 = blockIdx.x * kRows;
  if (threadIdx.x == 0) {
    for (int i = 0; i < SW; ++i) { mbar_init(smem_u32(&fullW[i])); mbar_init(smem_u32(&emptyW[i])); }
    for (int i = 0; i < SE; ++i) { mbar_init(smem_u32(&fullE[i])); mbar_init(smem_u32(&emptyE[i])); }
    mbar_init(smem_u32(&accum));
    asm volatile("fence.mbarrier_init.release.cluster;");
    asm volatile("prefetch.tensormap [%0];" ::"l"((uint64_t)&mapW) : "memory");
    asm volatile("prefetch.tensormap [%0];" ::"l"((uint64_t)&mapE) : "memory");
  }
  if (warp == 3) {
    asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;" ::"r"(smem_u32(&tmem_slot)), "r"(tmem_cols));
    asm volatile("tcgen05.relinquish_alloc_permit.cta_group::1.sync.aligned;");
  }
  asm volatile("tcgen05.fence::before_thread_sync;");
  __syncthreads();
  asm volatile("tcgen05.fence::after_thread_sync;");
  const uint32_t tmem = tmem_slot;
  if (warp == 0 && lane == 0) {            // W producer: kbsW k-blocks (kbsW x 16 KB) per stage, L2 evict_first
    uint64_t pol;
    asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;" : "=l"(pol));
    const int nW = kKB / kbsW;
    for (int i = 0; i < nW; ++i) {
      const int s = i % SW;
      if (i >= SW) mbar_wait(smem_u32(&emptyW[s]), ((i / SW) - 1) & 1);
      const uint32_t fb = smem_u32(&fullW[s]);
      expect_tx(fb, wStage);
      if (hint)
        asm volatile("cp.async.bulk.tensor.3d.shared::cluster.global.mbarrier::complete_tx::bytes.L2::cache_hint [%0], [%1, {%3, %4, %5}], [%2], %6;"
                     ::"r"(wbase + s * wStage), "l"((uint64_t)&mapW), "r"(fb), "r"(0), "r"(m0), "r"(i * kbsW), "l"(pol) : "memory");
      else
        asm volatile("cp.async.bulk.tensor.3d.shared::cluster.global.mbarrier::complete_tx::bytes [%0], [%1, {%3, %4, %5}], [%2];"
                     ::"r"(wbase + s * wStage), "l"((uint64_t)&mapW), "r"(fb), "r"(0), "r"(m0), "r"(i * kbsW) : "memory");
    }
