        arr=(ctypes.c_void_p*6)(*[o.data_ptr() for o in outs]); assert l3(emb.data_ptr(),W.data_ptr(),bias.data_ptr(),arr,emb.shape[0],1,1,16,kbs,2,torch.cuda.current_stream().cuda_stream)==0
    return call
def md(kbs,SW,SE):
    def call(emb,W,bias,*outs):
        arr=(ctypes.c_void_p*6)(*[o.data_ptr() for o in outs]); assert ld(emb.data_ptr(),W.data_ptr(),bias.data_ptr(),arr,emb.shape[0],kbs,SW,SE,1,torch.cuda.current_stream().cuda_stream)==0
    return call
